#!/usr/bin/env node
/**
 * Writes the server's copy of the WhatsApp scenario registry from
 * `@duncit/communication`'s `src/wa-events.ts`.
 *
 * Why a generated file rather than an import: `server/src` imports zero
 * `@duncit/*` packages by design (rule 40) — the Docker image never copies
 * them. The registry used to be kept twice BY HAND, which made it the largest
 * clone in the repo (786 lines) and grew the duplication baseline with every
 * new scenario. Same arrangement as `generate-shipped-keys.mjs`.
 *
 * Run `node scripts/generate-wa-events.mjs` after editing the package registry;
 * `--check` fails instead of writing, which is what CI runs so a stale copy
 * cannot ship.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(ROOT, "packages/communication/src/wa-events.ts");
const OUT = join(ROOT, "server/src/modules/platform/whatsapp/whatsapp.events.generated.ts");
const NAME = "generate-wa-events";
const check = process.argv.includes("--check");

// The package's leading doc comment explains the package; everything after it
// is the registry itself.
const source = readFileSync(SOURCE, "utf8").replaceAll("\r\n", "\n");
const headerEnd = source.indexOf("*/\n");
if (!source.startsWith("/**") || headerEnd === -1) {
  console.error(`${NAME}: ${SOURCE} no longer opens with a doc comment — update this script`);
  process.exit(1);
}
const registry = source.slice(headerEnd + 3).replace(/^\n+/, "");

const file = `/**
 * GENERATED by \`node scripts/generate-wa-events.mjs\` from
 * \`packages/communication/src/wa-events.ts\` — do not edit; change the package.
 *
 * It is a generated FILE rather than an import because \`server/src\` takes no
 * \`@duncit/*\` dependency (rule 40) — the Docker image never copies those
 * packages, so the copy has to travel as data.
 */

${registry}`;

if (check) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8").replaceAll("\r\n", "\n");
  } catch {
    console.error(`${NAME}: ${OUT} is missing — run the script without --check`);
    process.exit(1);
  }
  if (current !== file) {
    console.error(
      `${NAME}: whatsapp.events.generated.ts is out of date with the package registry.\n` +
        "Run `node scripts/generate-wa-events.mjs` and commit the result.",
    );
    process.exit(1);
  }
  console.log(`${NAME}: whatsapp.events.generated.ts matches the package registry`);
} else {
  writeFileSync(OUT, file, "utf8");
  console.log(`${NAME}: wrote ${OUT.slice(ROOT.length + 1)}`);
}
